func renderCodeBox(s styles, row insightsdb.SessionRow, width int) string {
	var allLines []string

	// Files touched
	var fileLines []string
	for _, f := range row.FilesTouched {
		fileLines = append(fileLines, s.render(s.bullet, "• ")+f)
