// ... 
repoCheckpoints := buildRepoCheckpointSet(ctx)
return runSummaryTUI(ctx, rows, currentBranch, repoCheckpoints, generateForSession)
```

To:

```go
rows, err := loadSummarySessions(ctx, opts)
// ...
repoCheckpoints := buildRepoCheckpointSet(ctx)

// For the TUI path, supplement rows with repo-reachable sessions
// that may be older than the 200-recent window.
if !opts.OutputJSON && !IsAccessibleMode() && repoCheckpoints != nil {
    rows = supplementWithRepoSessions(ctx, rows, repoCheckpoints)
}
return runSummaryTUI(ctx, rows, currentBranch, repoCheckpoints, generateForSession)
```

#### Step 3: Add `supplementWithRepoSessions` helper in summary_cmd.go

```go
func supplementWithRepoSessions(ctx context.Context, existing []insightsdb.SessionRow, repoCheckpoints map[string]struct{}) []insightsdb.SessionRow {
    // Build a set of checkpoint IDs already loaded.
    seen := make(map[string]struct{}, len(existing))
    for _, row := range existing {
        key := row.CheckpointID + "/" + fmt.Sprintf("%d", row.SessionIndex)
        seen[key] = struct{}{}
    }

    // Collect checkpoint IDs we need but don't have yet.
    var missing []string
    for cpID := range repoCheckpoints {
        // We don't know session_index here, so just check by checkpoint_id prefix.
        // If any session for this checkpoint is already loaded, skip it.
        // (This is an approximation -- multi-session checkpoints are rare.)
        if _, ok := seen[cpID+"/0"]; !ok {
            missing = append(missing, cpID)
        }
    }
    if len(missing) == 0 {
        return existing
    }

    // Open a new DB connection for the supplemental query.
    worktreeRoot, err := paths.WorktreeRoot(ctx)
    if err != nil {
        return existing
    }
    idb, err := insightsdb.Open(filepath.Join(worktreeRoot, paths.EntireDir, "insights.db"))
    if err != nil {
        return existing
    }
    defer idb.Close()

    extra, err := idb.QueryByCheckpointIDs(ctx, missing)
    if err != nil {
        return existing
    }

    // Merge, deduplicating by (checkpoint_id, session_index).
    for _, row := range extra {
        key := row.CheckpointID + "/" + fmt.Sprintf("%d", row.SessionIndex)
        if _, ok := seen[key]; !ok {
            existing = append(existing, row)
            seen[key] = struct{}{}
        }
    }
    return existing
}
```

Wait -- there's a problem. The `supplementWithRepoSessions` function needs DB access, but `loadSummarySessions` opens and closes the DB. We need to restructure slightly. Let me reconsider.

Actually, a cleaner approach: refactor `loadSummarySessions` to accept the `repoCheckpoints` set and do the supplemental loading internally, within the same DB connection.

