package cli

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"testing"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/facets"
	"github.com/entireio/cli/cmd/entire/cli/insightsdb"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/summarytui"
	"github.com/entireio/cli/cmd/entire/cli/testutil"
	"github.com/stretchr/testify/require"
)

func TestNewRootCmd_RegistersSummaryCommand(t *testing.T) {
	t.Parallel()

	root := NewRootCmd()

	var found bool
	for _, cmd := range root.Commands() {
		if cmd.Name() == "summary" {
			found = true
			break
		}
	}

	require.True(t, found, "expected 'summary' command to be registered")
}

func TestSummaryCmd_HasExpectedMetadata(t *testing.T) {
	t.Parallel()

	cmd := newSummaryCmd()
	require.Equal(t, "summary [checkpoint-id]", cmd.Use)
	require.NotEmpty(t, cmd.Short)
	require.NotNil(t, cmd.RunE)
}

func TestSummaryCmd_AcceptsCheckpointArg(t *testing.T) {
	t.Parallel()

	cmd := newSummaryCmd()
	// Should accept 0 or 1 args
	require.NoError(t, cmd.Args(cmd, []string{}))
	require.NoError(t, cmd.Args(cmd, []string{"a1b2c3"}))
	require.Error(t, cmd.Args(cmd, []string{"a1b2c3", "extra"}))
}

func TestLoadSummarySessions_CheckpointPrefix(t *testing.T) {
	tmpDir := t.TempDir()
	testutil.InitRepo(t, tmpDir)
	testutil.WriteFile(t, tmpDir, "f.txt", "init")
	testutil.GitAdd(t, tmpDir, "f.txt")
	testutil.GitCommit(t, tmpDir, "init")
	t.Chdir(tmpDir)

	entireDir := filepath.Join(tmpDir, paths.EntireDir)
	require.NoError(t, os.MkdirAll(entireDir, 0o755))

	idb, err := insightsdb.Open(filepath.Join(entireDir, "insights.db"))
	require.NoError(t, err)
	defer func() { _ = idb.Close() }()

	now := time.Now()
	for i, cpID := range []string{"aabb11223344", "aabb55667788", "ccdd11223344"} {
		row := insightsdb.SessionRow{
			CheckpointID: cpID,
			SessionID:    fmt.Sprintf("sess-%d", i),
			SessionIndex: 0,
			Agent:        "Claude Code",
			CreatedAt:    now.Add(-time.Duration(i) * time.Hour),
		}
		require.NoError(t, idb.InsertSession(context.Background(), row))
	}
	_ = idb.Close()

	// Stub out refresh and TUI to avoid LLM calls
	origRefresh := summaryRefreshCacheIfStale
	summaryRefreshCacheIfStale = func(_ context.Context, _ *insightsdb.InsightsDB) error { return nil }
	t.Cleanup(func() {
		summaryRefreshCacheIfStale = origRefresh
	})

	// Prefix matching two sessions
	rows, err := loadSummarySessions(context.Background(), summaryOptions{CheckpointPrefix: "aabb"})
	require.NoError(t, err)
	require.Len(t, rows, 2)

	// Exact match
	rows, err = loadSummarySessions(context.Background(), summaryOptions{CheckpointPrefix: "ccdd11223344"})
	require.NoError(t, err)
	require.Len(t, rows, 1)
	require.Equal(t, "ccdd11223344", rows[0].CheckpointID)

	// No match
	_, err = loadSummarySessions(context.Background(), summaryOptions{CheckpointPrefix: "ffffff"})
	require.Error(t, err)
	require.Contains(t, err.Error(), "checkpoint not found")
}

//nolint:musttag // nested external structs are part of the intended JSON payload
func TestRenderSummaryJSON_EncodesSessionSummaryAndFacets(t *testing.T) {
	t.Parallel()

	var buf bytes.Buffer
	rows := []insightsdb.SessionRow{sampleSummarySessionRow()}

	require.NoError(t, renderSummaryJSON(&buf, rows))

	var decoded []summarySessionView
	require.NoError(t, json.Unmarshal(buf.Bytes(), &decoded))
	require.Len(t, decoded, 1)
	require.Equal(t, "chk-summary", decoded[0].CheckpointID)
	require.Equal(t, "Fix flaky tests", decoded[0].Summary.Intent)
	require.Equal(t, "Reuse the existing summary pipeline", decoded[0].Summary.ImplementationRationale[0])
	require.Len(t, decoded[0].Facets.MissingContext, 1)
	require.Equal(t, "Run canary after prompt wording changes", decoded[0].Facets.MissingContext[0].Item)
}

func TestRenderSummaryText_ShowsSummaryAndFacetSections(t *testing.T) {
